import sys
from collections import deque
from typing import List

def solve(grid: List[List[int]]) -> int:
    if not grid:
        return 0
    h = len(grid)
    w = len(grid[0])

    # Count 4-connected components of non-zero cells
    visited = [[False] * w for _ in range(h)]
    components = 0
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0 and not visited[i][j]:
                components += 1
                dq = deque([(i, j)])
                visited[i][j] = True
                while dq:
                    x, y = dq.popleft()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w:
                            if not visited[nx][ny] and grid[nx][ny] != 0:
                                visited[nx][ny] = True
                                dq.append((nx, ny))

    if components == 0:
        return 0

    # Detect holes: zero-components that do not touch the boundary
    visited_zero = [[False] * w for _ in range(h)]
    has_hole = False
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 and not visited_zero[i][j]:
                touches_boundary = False
                dq = deque([(i, j)])
                visited_zero[i][j] = True
                while dq:
                    x, y = dq.popleft()
                    if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                        touches_boundary = True
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
