                                visited_zero[nx][ny] = True
                                dq.append((nx, ny))
                if not touches_boundary:
                    has_hole = True
                    # can break early, but continuing is fine
                    # break out of loops for efficiency
                    # i = h; break
    # Compute base value: ceil(6 / components)
    base = (6 + components - 1) // components
    if has_hole:
        base -= 1
    return base

